  "metric_catalog": [
    {
      "metric": "fleet_utilization",
      "description": "اشغال ناوگان",
      "formula": "بار مفید تقسیم بر ظرفیت",
      "unit": "درصد",
      "dimensions": [
        "vehicle_class"
      ]
