  "data_catalog": [
    {
      "dataset": "delivery_complaints",
      "description": "شکایت شعبه از تحویل",
      "dimensions": [
        "region",
        "week"
      ],
      "measures": [
        "complaints"
      ]
    },
    {
      "dataset": "delivery_routes",
      "description": "عملکرد مسیرهای توزیع هفتگی",
